const secoes = {};

// Usamos o caminho exato que você forneceu para pegar a lista de links.
const listaDeLinks = $input.first().json.links;

// Verificamos se a lista realmente existe e é um array para evitar erros.
if (listaDeLinks && Array.isArray(listaDeLinks)) {

    // Loop através da lista de URLs que foi encontrada com sucesso.
    for (const urlString of listaDeLinks) {
        if (!urlString) {
            continue;
        }

        try {
            // Lógica de parsing de texto (a mesma que já está robusta)
            let pathname = '';
            const domainIndex = urlString.indexOf('//') + 2;
            const pathIndex = urlString.indexOf('/', domainIndex);

            if (pathIndex !== -1) {
                pathname = urlString.substring(pathIndex);
            }

            if (pathname.includes('?')) {
                pathname = pathname.split('?')[0];
            }
            if (pathname.includes('#')) {
                pathname = pathname.split('#')[0];
            }

            pathname = pathname.replace(/^\/|\/$/g, '');

            if (!pathname) {
                continue;
            }

            const pathParts = pathname.split('/');
            const categoriaPrincipal = pathParts[0];

            // Lógica de categorização
            if (pathParts.length === 1) {
                if (categoriaPrincipal.includes('-')) {
                    const [secao, ...subsecaoParts] = categoriaPrincipal.split('-');
                    const subsecao = subsecaoParts.join('-');
                    if (!secoes[secao]) secoes[secao] = {};
                    secoes[secao][subsecao] = urlString;
                } else {
                    if (!secoes[categoriaPrincipal]) secoes[categoriaPrincipal] = [];
                    secoes[categoriaPrincipal].push(urlString);
                }
            } else {
                // Ignora links de paginação
                if (pathParts[pathParts.length - 2] === 'page') {
                    continue;
                }
                const secao = categoriaPrincipal;
                const subsecao = pathParts.slice(1).join('_');
                if (!secoes[secao]) secoes[secao] = {};
                secoes[secao][subsecao] = urlString;
            }
        } catch (e) {
            // Colocamos o try/catch de volta por segurança
            console.error(`Falha ao processar a URL: ${urlString}. Erro: ${e.message}`);
        }
    }
}

// Retorna o objeto JSON final com todos os links categorizados.
return [{ json: secoes }];

