function curarConteudoWeb(textoLimpo) {
  // Lista de espaços e suas informações
  const espacos = [];

  // Divide o texto em blocos por espaço
  const blocos = textoLimpo.split(/##\s+\[([^\]]+)\]\([^\)]+\)/);

  // Processa cada bloco
  for (let i = 1; i < blocos.length; i += 2) {
    const nome = blocos[i].trim();
    const descricao = blocos[i + 1] ? blocos[i + 1].trim() : '';

    // Extrai URL do link
    const urlMatch = textoLimpo.match(new RegExp('\\[' + nome.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\]\\(([^\\)]+)\\)'));
    const url = urlMatch ? urlMatch[1] : '';

    // Analisa a descrição para extrair informações
    let capacidade = 'Não informado';
    let localizacao = 'Belo Horizonte';
    let preco = 'Sob consulta';
    let tiposEvento = 'Casamento, Evento empresarial, Festa';

    // Busca capacidade na descrição
    const capacidadePatterns = [
      /capacidade\s*(?:para\s*)?(?:até\s*)?(\d+)\s*(?:a\s*)?(\d+)?\s*(?:pessoas|convidados)/i,
      /comporta\s*(?:até\s*)?(\d+)\s*(?:a\s*)?(\d+)?\s*(?:pessoas|convidados)/i,
      /(\d+)\s*(?:a\s*)?(\d+)?\s*(?:pessoas|convidados)/i,
      /até\s*(\d+)\s*pessoas/i
    ];

    for (const pattern of capacidadePatterns) {
      const match = descricao.match(pattern);
      if (match) {
        if (match[2]) {
          capacidade = match[1] + ' a ' + match[2] + ' convidados';
        } else {
          capacidade = 'Até ' + match[1] + ' convidados';
        }
        break;
      }
    }

    // Busca localização específica
    const locPatterns = [
      /(Pampulha|Orla da Lagoa|Prado|Contagem|Nova Lima)/i,
      /(?:localizado|situado)\s*(?:em|na|no)\s*([^,\.]+)/i
    ];

    for (const pattern of locPatterns) {
      const match = descricao.match(pattern);
      if (match) {
        localizacao = 'Belo Horizonte' + (match[1] ? ', ' + match[1].trim() : '');
        break;
      }
    }

    // Busca informações de área
    const areaMatch = descricao.match(/(\d+\.?\d*)\s*m²/i);
    const areaInfo = areaMatch ? 'Área de ' + areaMatch[1] + 'm²' : '';

    // Extrai características especiais
    const caracteristicas = [];
    if (descricao.match(/sofisticad/i)) caracteristicas.push('Ambiente sofisticado');
    if (descricao.match(/acolhedor/i)) caracteristicas.push('Atmosfera acolhedora');
    if (descricao.match(/moderno/i)) caracteristicas.push('Estrutura moderna');
    if (descricao.match(/rústico/i)) caracteristicas.push('Estilo rústico');
    if (descricao.match(/íntimo/i)) caracteristicas.push('Ideal para eventos íntimos');
    if (descricao.match(/verde|jardim|natureza/i)) caracteristicas.push('Área verde');

    // Casos especiais conhecidos
    if (nome === 'Espaço Origem') {
      capacidade = 'Até 2600 convidados';
    }
    if (nome === 'Sítio Pampulha') {
      if (!areaInfo.includes('3200')) {
        caracteristicas.push('Área total de 3.200m² (2.000m² de lazer)');
      }
    }

    espacos.push({
      nome: nome,
      capacidade: capacidade,
      tiposEvento: tiposEvento,
      localizacao: localizacao,
      preco: preco,
      url: url,
      areaInfo: areaInfo,
      caracteristicas: caracteristicas,
      descricaoOriginal: descricao.substring(0, 200) + '...'
    });
  }

  // Formata o resultado final
  let resultado = '### Espaços para Casamento em Belo Horizonte - Grupo Mallard\n\n';
  resultado += 'O Grupo Mallard oferece uma seleção exclusiva de espaços para casamentos e eventos em Belo Horizonte e região. ';
  resultado += 'Com opções que atendem de 50 a 2600 convidados, nossos espaços combinam elegância, conforto e infraestrutura completa.\n\n';
  resultado += '---\n\n';
  resultado += '### Espaços Disponíveis\n\n';

  espacos.forEach((espaco, index) => {
    resultado += '#### ' + (index + 1) + '. ' + espaco.nome + '\n';
    resultado += '* **Capacidade:** ' + espaco.capacidade + '\n';
    resultado += '* **Tipos de evento:** ' + espaco.tiposEvento + '\n';
    resultado += '* **Localização:** ' + espaco.localizacao + '\n';
    if (espaco.areaInfo) {
      resultado += '* **Área:** ' + espaco.areaInfo + '\n';
    }
    resultado += '* **Valor:** ' + espaco.preco + '\n';

    if (espaco.caracteristicas.length > 0) {
      resultado += '\n**Características:**\n';
      espaco.caracteristicas.forEach(carac => {
        resultado += '- ' + carac + '\n';
      });
    }

    resultado += '\n[Ver mais detalhes](' + espaco.url + ')\n';
    resultado += '\n---\n\n';
  });

  resultado += '### Serviços Inclusos\n\n';
  resultado += 'Todos os espaços do Grupo Mallard contam com:\n';
  resultado += '* Buffet próprio assinado pela Chef Simone Caldas\n';
  resultado += '* Diversas opções gastronômicas personalizadas\n';
  resultado += '* Equipe especializada em eventos\n';
  resultado += '* Infraestrutura completa\n';
  resultado += '* Estacionamento\n';
  resultado += '* Decoração básica\n\n';
  resultado += '### Contato para Orçamento\n\n';
  resultado += '**WhatsApp:** (31) 99275-8121\n\n';
  resultado += 'Solicite uma proposta personalizada e agende uma visita para conhecer nossos espaços.\n\n';
  resultado += '**Empresa:** Mallard Recepções LTDA';

  // Cria também um array separado com os dados estruturados
  const dadosEstruturados = espacos.map(espaco => ({
    nome: espaco.nome,
    capacidade: espaco.capacidade,
    tiposEvento: espaco.tiposEvento,
    localizacao: espaco.localizacao,
    preco: espaco.preco,
    url: espaco.url,
    caracteristicas: espaco.caracteristicas.join('; ')
  }));

  return {
    conteudoCurado: resultado,
    espacos: dadosEstruturados
  };
}

