// Função principal de curadoria de conteúdo
function curarConteudoWeb(textoHTML) {
  // Primeiro, extrai os links das imagens antes de limpar o HTML
  const imagensMap = {};

  // Lista conhecida de espaços
  const espacosConhecidos = [
    'Mallard Recepções',
    'Casa Orla', 
    'Pontal da Lagoa',
    'Chalé Pampulha',
    'Sítio Pampulha',
    'Espaço Maggiore',
    'Innovare Centro de Eventos',
    'Espaço Floricultura',
    'Recanto Cascata da Lagoa',
    'Espaço Origem'
  ];

  // Para cada espaço, busca as imagens relacionadas
  espacosConhecidos.forEach(espaco => {
    const nomeSimplificado = espaco.toLowerCase()
      .replace(/ç/g, 'c')
      .replace(/ã/g, 'a')
      .replace(/á/g, 'a')
      .replace(/é/g, 'e')
      .replace(/í/g, 'i')
      .replace(/ó/g, 'o')
      .replace(/ú/g, 'u')
      .replace(/\s+/g, '-');

    // Regex para encontrar imagens relacionadas ao espaço
    const regexImagem = new RegExp('(?:src|data-lazy-src|srcset)=["\']([^"\']*' + nomeSimplificado + '[^"\']*)["\'](.*?)(?:>|/>)', 'gi');
    const matches = textoHTML.matchAll(regexImagem);

    const imagens = [];
    for (const match of matches) {
      let url = match[1];
      // Limpa a URL e pega apenas a primeira de srcset se houver múltiplas
      url = url.split(' ')[0].split(',')[0].trim();
      if (url && !url.includes('svg+xml') && !url.includes('data:image')) {
        // Adiciona https se necessário
        if (!url.startsWith('http')) {
          url = 'https://grupomallard.com' + (url.startsWith('/') ? '' : '/') + url;
        }
        // Remove .webp se houver e pega o .jpg original
        url = url.replace('.webp', '').replace('.jpg.jpg', '.jpg');
        if (!imagens.includes(url)) {
          imagens.push(url);
        }
      }
    }

    if (imagens.length > 0) {
      imagensMap[espaco] = imagens[0]; // Pega a primeira imagem principal
    }
  });

  // Remove todas as tags HTML e scripts
  let texto = textoHTML
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const espacos = [];

  // Processa cada espaço conhecido
  espacosConhecidos.forEach((nome, index) => {
    const regexNome = new RegExp(nome + '[\\s\\S]*?(?=(?:' + espacosConhecidos.join('|') + ')|$)', 'i');
    const blocoTexto = texto.match(regexNome);

    if (blocoTexto) {
      const bloco = blocoTexto[0];

      // Extrai informações do bloco
      const capacidadeMatch = bloco.match(/(\d+)[-–](\d+)\s*(?:convidados|Convidados)/i);
      const precoMatch = bloco.match(/A\s*partir\s*de\s*R\$\s*([\d.,]+)/);
      const locMatch = bloco.match(/(Belo\s*Horizonte|Contagem|Nova\s*Lima)/);

      espacos.push({
        nome: nome,
        capacidade: capacidadeMatch ? capacidadeMatch[1] + ' a ' + capacidadeMatch[2] + ' convidados' : 'Não informado',
        tiposEvento: 'Casamento, Evento empresarial, Festa',
        localizacao: locMatch ? locMatch[1] : 'Belo Horizonte',
        preco: precoMatch ? 'A partir de R$ ' + precoMatch[1] : 'Sob consulta',
        imagem: imagensMap[nome] || ''
      });
    }
  });

  // Formata o resultado final
  let resultado = '### Espaços para Casamento em Belo Horizonte - Grupo Mallard\n\n';
  resultado += 'O Grupo Mallard oferece uma seleção exclusiva de espaços para casamentos e eventos em Belo Horizonte e região. ';
  resultado += 'Com opções que atendem de 50 a 800 convidados, nossos espaços combinam elegância, conforto e infraestrutura completa.\n\n';
  resultado += '---\n\n';
  resultado += '### Espaços Disponíveis\n\n';

  espacos.forEach((espaco, index) => {
    resultado += '#### ' + (index + 1) + '. ' + espaco.nome + '\n';
    if (espaco.imagem) {
      resultado += '![' + espaco.nome + '](' + espaco.imagem + ')\n\n';
    }
    resultado += '* **Capacidade:** ' + espaco.capacidade + '\n';
    resultado += '* **Tipos de evento:** ' + espaco.tiposEvento + '\n';
    resultado += '* **Localização:** ' + espaco.localizacao + '\n';
    resultado += '* **Valor:** ' + espaco.preco + '\n';
    resultado += '\n---\n\n';
  });

  resultado += '### Serviços Inclusos\n\n';
  resultado += 'Todos os espaços do Grupo Mallard contam com:\n';
  resultado += '* Buffet próprio assinado pela Chef Simone Caldas\n';
  resultado += '* Diversas opções gastronômicas personalizadas\n';
  resultado += '* Equipe especializada em eventos\n';
  resultado += '* Infraestrutura completa\n';
  resultado += '* Estacionamento\n';
  resultado += '* Decoração básica\n\n';
  resultado += '### Contato para Orçamento\n\n';
  resultado += '**WhatsApp:** (31) 99275-8121\n\n';
  resultado += 'Solicite uma proposta personalizada e agende uma visita para conhecer nossos espaços.\n\n';
  resultado += '**Empresa:** Mallard Recepções LTDA';

  // Cria também um array separado com os dados estruturados incluindo imagens
  const dadosEstruturados = espacos.map(espaco => ({
    nome: espaco.nome,
    capacidade: espaco.capacidade,
    tiposEvento: espaco.tiposEvento,
    localizacao: espaco.localizacao,
    preco: espaco.preco,
    imagemUrl: espaco.imagem
  }));

  return {
    conteudoCurado: resultado,
    espacos: dadosEstruturados
  };
}

