if ($input.item && $input.item.json && $input.item.json.texto) {
  textoHTML = $input.item.json.texto;
} else if ($input.item && $input.item.json && $input.item.json.content) {
  textoHTML = $input.item.json.content;
} else if ($input.item && $input.item.json && $input.item.json.html) {
  textoHTML = $input.item.json.html;
} else if ($input.item && $input.item.json) {
